<?php use App\Core\Config; $register=($mode??'login')==='register';$setup=($mode??'')==='setup';?>
<div class="container page-space"><div class="auth-card"><div class="eyebrow">SPAȚIUL PRODUCĂTORULUI</div><h1 class="page-title"><?=e($title)?></h1><p class="muted"><?=$setup?'Creează contul administratorului și prima organizație.':($register?'Un spațiu pentru produsele și loturile organizației tale.':'Continuă administrarea produselor tale.')?></p>
<?php if($register&&!Config::get('registration_enabled')):?><p>Înscrierile se fac prin administratorul platformei.</p><?php else:?>
<form method="post" action="<?=$setup?'/setup':($register?'/register':'/login')?>" class="form-stack"><?=csrf()?>
<?php if($setup):?><label>Token de instalare<input class="form-control" name="setup_token" type="password" required autocomplete="off"></label><?php endif?>
<?php if($setup||$register):?><label>Numele tău<input class="form-control" name="display_name" required maxlength="120" autocomplete="name"></label><label>Denumirea organizației<input class="form-control" name="organization" required maxlength="180" autocomplete="organization"></label><?php endif?>
<label>Email<input class="form-control" type="email" name="email" required maxlength="190" autocomplete="username"></label><label>Parolă<input class="form-control" type="password" name="password" required <?=$setup||$register?'minlength="12"':''?> maxlength="<?=$setup||$register?\App\Core\Passwords::maxBytes():200?>" autocomplete="<?=$setup||$register?'new-password':'current-password'?>"></label><button class="btn btn-primary" type="submit"><?=$setup?'Configurează platforma':($register?'Creează contul':'Intră în cont')?> <?=icon('arrow')?></button></form>
<?php if(!$register&&!$setup):?><p class="mt-3"><a href="/recuperare">Ai uitat parola?</a></p><?php endif?><?php if(!$register&&!$setup&&Config::get('registration_enabled')):?><p class="mt-4">Nu ai cont? <a href="/register">Înregistrează producătorul</a></p><?php endif?><?php endif?></div></div>
